hunts.query:
// Hunt: HB-CL-003 - Sign-in from Known Anonymizer or Tor Exit Node
// MITRE ATT&CK: T1090 (Proxy)
// Platform: Microsoft Sentinel (SigninLogs)
//
// Description: Identifies user sign-in activity originating from anonymizing proxies,
// Tor exit nodes, or high-risk IP sources flagged by Entra ID Protection risk signals
// or anonymizer network telemetry.

let lookback = 7d;
let anonymizerRiskSignals = dynamic(["anonymousIp", "anonymizedIP", "torExitNode", "maliciousIP"]);
SigninLogs
| where TimeGenerated > ago(lookback)
| where RiskDetail in~ (anonymizerRiskSignals) 
    or tostring(NetworkLocationDetails) has_any ("Tor", "Anonymizer", "Proxy")
| summarize 
    FirstSeen = min(TimeGenerated),
    LastSeen = max(TimeGenerated),
    Attempts = count(),
    SuccessCount = countif(ResultType == "0"),
    FailureCount = countif(ResultType != "0"),
    TargetApps = make_set(AppDisplayName, 10),
    UserAgents = make_set(UserAgent, 5)
    by UserPrincipalName, IPAddress, Location, RiskDetail
| extend SigninStatus = iff(SuccessCount > 0, "Compromise Likely (Successful)", "Probing (Failed Only)")
| project FirstSeen, LastSeen, UserPrincipalName, IPAddress, Location, RiskDetail, SigninStatus, Attempts, SuccessCount, FailureCount, TargetApps, UserAgents
| order by SuccessCount desc, Attempts desc

// Hunt: HB-CL-004 - Azure Resource Deletion Burst
// MITRE ATT&CK: T1485 (Data Destruction)
// Platform: Microsoft Sentinel (AzureActivity)
//
// Description: Detects a rapid sequence of cloud resource deletions (VMs, storage accounts, 
// databases, key vaults) by a single identity within a short time window, indicating 
// potential cloud extortion, ransomware impact, or rogue administrator activity.

let lookback = 24h;
let burstWindow = 30m;
let deletionThreshold = 3;
AzureActivity
| where TimeGenerated > ago(lookback)
| where ActivityStatusValue in~ ("Success", "Succeeded")
| where OperationNameValue endswith "/delete"
| summarize 
    FirstDeletion = min(TimeGenerated),
    LastDeletion = max(TimeGenerated),
    DeletionCount = count(),
    DeletedOperations = make_set(OperationNameValue, 10),
    ResourceGroups = make_set(ResourceGroup, 10),
    SourceIPs = make_set(CallerIpAddress, 5)
    by Caller, SubscriptionId, bin(TimeGenerated, burstWindow)
| where DeletionCount >= deletionThreshold
| extend DurationMinutes = datetime_diff('minute', LastDeletion, FirstDeletion)
| project FirstDeletion, LastDeletion, DurationMinutes, Caller, SubscriptionId, DeletionCount, DeletedOperations, ResourceGroups, SourceIPs
| order by DeletionCount desc

// Hunt: HB-ID-001 - Password Spray Against Multiple Accounts
// MITRE ATT&CK: T1110.003 (Password Spraying)
// Platform: Microsoft Sentinel (SigninLogs)
//
// Description: Detects a single IP address attempting passwords across multiple accounts,
// performing two-stage correlation with subsequent successful sign-ins across the targeted
// users to identify both failed spray probes and high-priority account compromises.

let lookback = 1d;
let window = 30m;
let minUsers = 10;
let followUpWindow = 2h;
let SprayFailures = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType in ("50126", "50053")
| summarize 
    FirstFailure = min(TimeGenerated),
    LastFailure = max(TimeGenerated),
    FailedUsers = dcount(UserPrincipalName),
    Attempts = count(),
    TargetUsers = make_set(UserPrincipalName, 50)
    by SprayIP = IPAddress, bin(TimeGenerated, window)
| where FailedUsers >= minUsers;
let SuccessLogins = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType == "0"
| project SuccessTime = TimeGenerated, UserPrincipalName, SuccessIP = IPAddress, AppDisplayName, UserAgent;
SprayFailures
| mv-expand TargetUser = TargetUsers to typeof(string)
| join kind=leftouter (
    SuccessLogins
) on $left.TargetUser == $right.UserPrincipalName
| where isempty(SuccessTime) or (SuccessTime between (FirstFailure .. (LastFailure + followUpWindow)))
| summarize 
    FirstSpray = min(FirstFailure),
    LastSpray = max(LastFailure),
    SprayedAccounts = take_any(FailedUsers),
    TotalAttempts = take_any(Attempts),
    CompromisedAccounts = dcountif(TargetUser, isnotempty(SuccessTime)),
    SuccessfulUsers = make_set_if(TargetUser, isnotempty(SuccessTime), 10),
    SuccessIPs = make_set_if(SuccessIP, isnotempty(SuccessTime), 5),
    SuccessApps = make_set_if(AppDisplayName, isnotempty(SuccessTime), 5)
    by SprayIP, bin(TimeGenerated, window)
| extend CompromiseStatus = case(
    CompromisedAccounts > 0 and set_has_element(SuccessIPs, SprayIP), "Direct Compromise (Same IP)",
    CompromisedAccounts > 0, "Correlated Compromise (Different IP)",
    "Spray Probing Only (No Success)"
)
| project TimeGenerated, SprayIP, CompromiseStatus, SprayedAccounts, TotalAttempts, 
          CompromisedAccounts, SuccessfulUsers, SuccessIPs, SuccessApps, FirstSpray, LastSpray
| order by CompromisedAccounts desc, SprayedAccounts desc

// Hunt: HB-ID-002 - Targeted Brute Force Against Single Account Followed by Success
// MITRE ATT&CK: T1110 (Brute Force)
// Platform: Microsoft Sentinel (SigninLogs)
//
// Description: Detects a concentrated burst of failed authentication attempts against a specific
// user account followed chronologically by a successful sign-in within a follow-up window,
// correlating whether success originated from the attack IP or an alternative egress point.

let lookback = 1d;
let window = 1h;
let minFailures = 10;
let followUpWindow = 2h;
let BruteForceFailures = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType in ("50126", "50053")
| summarize 
    FailureCount = count(),
    FirstFailure = min(TimeGenerated),
    LastFailure = max(TimeGenerated),
    FailureIPs = make_set(IPAddress, 5)
    by UserPrincipalName, bin(TimeGenerated, window)
| where FailureCount >= minFailures;
let SuccessfulLogins = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType == "0"
| project SuccessTime = TimeGenerated, UserPrincipalName, SuccessIP = IPAddress, AppDisplayName, UserAgent;
BruteForceFailures
| join kind=inner (
    SuccessfulLogins
) on UserPrincipalName
| where SuccessTime between (LastFailure .. (LastFailure + followUpWindow))
| extend SuccessFromAttackIP = set_has_element(FailureIPs, SuccessIP)
| project UserPrincipalName, FailureCount, FirstFailure, LastFailure, 
          SuccessTime, SuccessIP, FailureIPs, SuccessFromAttackIP, AppDisplayName, UserAgent
| order by LastFailure desc

// Hunt: HB-ID-004 - MFA Fatigue Attack Followed by Success
// MITRE ATT&CK: T1621 (Multi-Factor Authentication Request Generation)
// Platform: Microsoft Sentinel (SigninLogs)
//
// Description: Detects repeated multi-factor authentication push rejections or timeouts
// (ResultType 500121 or MFA failure descriptions) against a user account followed chronologically
// by a successful login within a sliding follow-up window, identifying MFA fatigue compromises
// without tumbling bucket-boundary blindspots.

let lookback = 1d;
let window = 20m;
let minDenials = 3;
let followUpWindow = 30m;
let MfaDenials = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType in ("500121", "50074") 
    or ResultDescription has_any ("MFA denied", "declined the authentication", "mobile app notification", "fraud reported")
| summarize 
    DenialCount = count(),
    FirstDenial = min(TimeGenerated),
    LastDenial = max(TimeGenerated),
    DenialIPs = make_set(IPAddress, 5),
    FailureDescriptions = make_set(ResultDescription, 3)
    by UserPrincipalName, bin(TimeGenerated, window)
| where DenialCount >= minDenials;
let SuccessLogins = SigninLogs
| where TimeGenerated > ago(lookback)
| where ResultType == "0"
| project SuccessTime = TimeGenerated, UserPrincipalName, SuccessIP = IPAddress, AppDisplayName, UserAgent;
MfaDenials
| join kind=inner (
    SuccessLogins
) on UserPrincipalName
| where SuccessTime between (LastDenial .. (LastDenial + followUpWindow))
| extend SuccessFromSameIP = set_has_element(DenialIPs, SuccessIP)
| project UserPrincipalName, DenialCount, FirstDenial, LastDenial,
          SuccessTime, SuccessIP, DenialIPs, SuccessFromSameIP,
          AppDisplayName, UserAgent, FailureDescriptions
| order by LastDenial desc

// Hunt: HB-PS-004 - WMI Event Subscription Persistence
// MITRE ATT&CK: T1546.003 (Event Triggered Execution: Windows Management Instrumentation Event Subscription)
// Platform: Microsoft Defender XDR (DeviceEvents)
//
// Description: Detects the creation of permanent WMI event filters, consumers, and bindings.
// Adversaries establish WMI subscriptions to maintain stealthy persistence and execute malicious code
// upon specific OS triggers (e.g., system startup, network connection, user logon).

let lookback = 14d;
let wmiActions = dynamic([
    "WmiEventConsumerCreated",
    "WmiEventFilterCreated",
    "WmiEventConsumerToFilterCreated"
]);
DeviceEvents
| where Timestamp > ago(lookback)
| where ActionType in~ (wmiActions) or ActionType has "WmiEvent"
| extend ConsumerName = coalesce(tostring(AdditionalFields.ConsumerName), tostring(AdditionalFields.Consumer), tostring(AdditionalFields.Name))
| extend FilterName = coalesce(tostring(AdditionalFields.FilterName), tostring(AdditionalFields.Filter))
| extend Query = coalesce(tostring(AdditionalFields.Query), tostring(AdditionalFields.QueryText))
| project Timestamp, DeviceName, ActionType, ConsumerName, FilterName, Query,
          InitiatingProcessFileName, InitiatingProcessCommandLine, AccountName, AdditionalFields
| order by Timestamp desc

// Hunt: HB-RW-002 - Ransomware Mass File Rename with Encrypted Extension
// MITRE ATT&CK: T1486 (Data Encrypted for Impact)
// Platform: Microsoft Defender XDR (DeviceFileEvents)
//
// Description: Detects a rapid burst of file rename operations where documents are appended with
// known ransomware extensions or stripped of standard document extensions by an untrusted process,
// serving as a behavioral precursor indicator of active data encryption.

let lookback = 24h;
let burstWindow = 10m;
let renameThreshold = 20;
let knownRansomExts = dynamic([
    "locked", "lockbit", "crypted", "crypto", "enc", "wnry", "payme",
    "ransom", "blackcat", "alphv", "hive", "mallox", "stop", "djvu"
]);
let targetDocumentExts = dynamic([
    "doc", "docx", "xls", "xlsx", "ppt", "pptx", "pdf", "txt", "csv", 
    "rtf", "jpg", "jpeg", "png", "pst", "ost", "db", "sql", "zip", "7z"
]);
let trustedProcesses = dynamic([
    "devenv.exe", "msbuild.exe", "git.exe", "onedrive.exe", "dropbox.exe", 
    "robocopy.exe", "msiexec.exe", "tiworker.exe", "trustedinstaller.exe"
]);
DeviceFileEvents
| where Timestamp > ago(lookback)
| where ActionType == "FileRenamed"
| where not(InitiatingProcessFileName in~ (trustedProcesses))
| extend CurrentExt = tolower(tostring(split(FileName, ".")[-1]))
| extend PrevExt = tolower(tostring(split(PreviousFileName, ".")[-1]))
| where CurrentExt != PrevExt
| where CurrentExt in~ (knownRansomExts) 
    or (PrevExt in~ (targetDocumentExts) and not(CurrentExt in~ (targetDocumentExts)))
| summarize 
    FirstRename = min(Timestamp),
    LastRename = max(Timestamp),
    RenameCount = count(),
    SampleNewFiles = make_set(FileName, 5),
    SampleOldFiles = make_set(PreviousFileName, 5),
    TargetFolders = make_set(FolderPath, 5)
    by DeviceName, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessAccountName, bin(Timestamp, burstWindow)
| where RenameCount >= renameThreshold
| extend DurationSeconds = datetime_diff('second', LastRename, FirstRename)
| project FirstRename, LastRename, DurationSeconds, DeviceName, InitiatingProcessFileName,
          InitiatingProcessAccountName, RenameCount, SampleNewFiles, SampleOldFiles, TargetFolders, InitiatingProcessCommandLine
| order by RenameCount desc

// Hunt: HB-RW-003 - Safe-Mode or Boot Recovery Disabled via Bcdedit
// MITRE ATT&CK: T1490 (Inhibit System Recovery)
// Platform: Microsoft Defender XDR (DeviceProcessEvents)
//
// Description: Detects the execution of bcdedit.exe with command-line switches designed
// to disable Windows automatic startup recovery or tamper with safe-mode configuration,
// a classic ransomware precursor designed to inhibit incident response and recovery.

let lookback = 7d;
let recoveryTamperingArgs = dynamic([
    "recoveryenabled", "bootstatuspolicy", "ignoreallfailures", "safeboot"
]);
DeviceProcessEvents
| where Timestamp > ago(lookback)
| where FileName =~ "bcdedit.exe" or ProcessCommandLine has "bcdedit"
| where ProcessCommandLine has_any (recoveryTamperingArgs)
| extend TamperedFeature = case(
    ProcessCommandLine has "recoveryenabled", "Recovery Disabled",
    ProcessCommandLine has "bootstatuspolicy", "Failure Policy Tampered",
    ProcessCommandLine has "safeboot", "SafeBoot Modified",
    "Other Boot Config Change"
)
| project Timestamp, DeviceName, TamperedFeature, ProcessCommandLine,
          InitiatingProcessFileName, InitiatingProcessCommandLine,
          InitiatingProcessAccountName, AccountName, ProcessIntegrityLevel
| order by Timestamp desc
